123: export async function schemaForProject(directory: string): Promise<string> {
124:   const canonical = await canonicalProjectPath(directory);
125:   const normalized =
126:     process.platform === "win32" ? canonical.toLowerCase() : canonical;
127:   const digest = crypto
128:     .createHash("sha256")
129:     .update(normalized)
130:     .digest("hex")
131:     .slice(0, 12);
132:   return `remembering_${digest}`;
