158: function parseEmbedding(raw: RawConfig): EmbeddingConfig {
159:   const provider =
160:     nonEmptyString(process.env.REMEMBERING_EMBEDDING_PROVIDER) ??
161:     nonEmptyString(raw.embedding?.provider) ??
162:     "ollama";
163:   if (provider === "hashing") {
164:     // The hashing embedder is a deterministic test double, never a
165:     // production retrieval model. It is only honoured for explicitly
166:     // opted-in local tests, never by silent fallback.
167:     if (process.env.REMEMBERING_ALLOW_TEST_EMBEDDINGS !== "1") {
168:       throw new Error(
169:         "Invalid OpenCode Remembering config: embedding.provider " +
170:           '"hashing" is a test double and is refused without ' +
171:           "REMEMBERING_ALLOW_TEST_EMBEDDINGS=1.",
172:       );
173:     }
174:   } else if (provider !== "ollama" && provider !== "sentence-transformers") {
175:     throw new Error(
176:       `Invalid OpenCode Remembering config: embedding.provider must be ` +
177:         `"ollama", "sentence-transformers" or "hashing", got ${JSON.stringify(provider)}.`,
178:     );
179:   }
180:   const model =
181:     nonEmptyString(process.env.REMEMBERING_EMBEDDING_MODEL) ??
182:     nonEmptyString(raw.embedding?.model) ??
183:     "bge-m3";
184:   const host =
185:     nonEmptyString(process.env.REMEMBERING_EMBEDDING_HOST) ??
186:     nonEmptyString(raw.embedding?.host) ??
187:     "http://localhost:11434";
188:   return { provider, model, host };
189: }
