230: export async function loadConfig(
231:   directory: string,
232: ): Promise<RememberingConfig> {
233:   const { raw } = await readRawConfig();
234:   rejectLegacyRoot(raw);
235: 
236:   const dsn =
237:     nonEmptyString(process.env.MEMORY_BASELINE_DSN) ??
238:     nonEmptyString(raw.dsn) ??
239:     "postgresql://postgres:postgres@localhost:5434/memory";
240: 
241:   const rawSchema = nonEmptyString(raw.schema);
242:   const schema =
243:     rawSchema !== undefined
244:       ? validateSchemaName(rawSchema)
245:       : await schemaForProject(directory);
246:   const autoInject =
247:     typeof raw.context?.auto_inject === "boolean"
248:       ? raw.context.auto_inject
249:       : true;
250: 
251:   return {
252:     dsn,
253:     schema,
254:     embedding: parseEmbedding(raw),
255:     retrieval: parseRetrieval(raw),
256:     context: {
257:       autoInject,
258:       maxChars: boundedInteger(raw.context?.max_chars, 4000, 256, 20000),
259:       maxResults: boundedInteger(raw.context?.max_results, 6, 1, 20),
260:     },
261:   };
262: }
