264: /**
265:  * The legacy runtime is gone: the memory engine is native TypeScript
266:  * (src/engine). A stale project_memory_root setting fails closed with
267:  * migration guidance instead of being silently ignored.
268:  */
269: function rejectLegacyRoot(raw: RawConfig): void {
270:   if (
271:     nonEmptyString(process.env.PROJECT_MEMORY_ROOT) !== undefined ||
272:     nonEmptyString(raw.project_memory_root) !== undefined
273:   ) {
274:     throw new Error(
275:       "Invalid OpenCode Remembering config: project_memory_root / " +
276:         "PROJECT_MEMORY_ROOT no longer exists. The memory engine is " +
277:         "native TypeScript (src/engine); remove " +
278:         "the setting — no replacement path is needed.",
279:     );
280:   }
281: }

