48: export async function extensionStatus(client: PoolClient, name: string): Promise<ExtensionStatus> {
49:   const installed = await client.query("SELECT extversion FROM pg_extension WHERE extname = $1", [name]);
50:   if (installed.rowCount && installed.rowCount > 0) {
51:     return { installed: true, version: String(installed.rows[0].extversion), software: true };
52:   }
53:   const available = await client.query(
54:     "SELECT default_version FROM pg_available_extensions WHERE name = $1",
55:     [name],
56:   );
57:   if (!available.rowCount) return { installed: false, version: null, software: false };
58:   return { installed: false, version: null, software: true };
59: }
