61: export async function ensureExtension(client: PoolClient, name: string): Promise<ExtensionStatus> {
62:   const status = await extensionStatus(client, name);
63:   if (status.installed) return status;
64:   if (!status.software) {
65:     throw new EngineError(
66:       "EXTENSION_UNAVAILABLE",
67:       `extension ${JSON.stringify(name)} is not installed in this PostgreSQL installation (pg_available_extensions has no such entry). Install the extension software first (e.g. the pgvector package for your server), then retry.`,
68:     );
69:   }
70:   if (name !== "vector" && name !== "pg_trgm") {
71:     throw new EngineError("CONFIG_INVALID", `refusing to enable unexpected extension ${JSON.stringify(name)}.`);
72:   }
73:   try {
74:     await client.query(`CREATE EXTENSION IF NOT EXISTS "${name.replace(/"/g, "")}"`);
75:   } catch (error) {
76:     const message = error instanceof Error ? error.message : String(error);
77:     const code = (error as { code?: string })?.code;
78:     if (code === "42501" || /permission denied/i.test(message)) {
79:       throw new EngineError(
80:         "EXTENSION_PERMISSION",
81:         `permission denied enabling extension ${JSON.stringify(name)}. Ask a database superuser to run CREATE EXTENSION ${name}; the configured role cannot enable it.`,
82:       );
83:     }
84:     throw new EngineError(
85:       "EXTENSION_UNAVAILABLE",
86:       `could not enable extension ${JSON.stringify(name)}: ${error instanceof Error ? error.name : "Error"}: ${message.slice(0, 200)}`,
87:     );
88:   }
89:   return extensionStatus(client, name);
90: }

