45:       await client.query("CREATE EXTENSION IF NOT EXISTS pg_trgm");
46:       await client.query(`CREATE SCHEMA IF NOT EXISTS ${s}`);
47:       await client.query(
48:         `CREATE TABLE IF NOT EXISTS ${s}.meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)`,
49:       );
50:       await client.query(
51:         `CREATE TABLE IF NOT EXISTS ${s}.sources (` +
52:           `source_id TEXT PRIMARY KEY, artifact_type TEXT NOT NULL, content_hash TEXT NOT NULL, ` +
53:           `timestamp TEXT, ingested_at TIMESTAMPTZ NOT NULL DEFAULT now())`,
54:       );
55:       // pgvector dimension is interpolated as an integer literal; the
56:       // schema name is validated and quoted above.
57:       const dim = Math.floor(embeddingDim);
58:       if (!Number.isInteger(dim) || dim < 1 || dim > 65535) {
59:         throw new EngineError("CONFIG_INVALID", `refusing invalid embedding dimension ${JSON.stringify(embeddingDim)}.`);
60:       }
61:       await client.query(
62:         `CREATE TABLE IF NOT EXISTS ${s}.chunks (` +
63:           `chunk_id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES ${s}.sources(source_id) ON DELETE CASCADE, ` +
64:           `ordinal INT NOT NULL, text TEXT NOT NULL, section TEXT, char_start INT NOT NULL, char_end INT NOT NULL, ` +
65:           `content_hash TEXT NOT NULL, chunker TEXT NOT NULL, embedding_version TEXT NOT NULL, ` +
66:           `embedding vector(${dim}) NOT NULL, tsv TSVECTOR NOT NULL)`,
