163:   async lexicalSearch(query: string, k: number): Promise<ScoredChunk[]> {
164:     const terms = query.toLowerCase().match(/[a-z0-9]+/g)?.filter((t) => t.length > 1) ?? [];
165:     if (terms.length === 0) return [];
166:     const orQuery = terms.join(" | ");
167:     const s = ident(this.schema);
168:     const client = await this.pool.connect();
169:     try {
170:       const res = await client.query(
171:         `SELECT chunk_id, source_id, text, section, ts_rank_cd(tsv, to_tsquery('english', $1)) ` +
172:           `FROM ${s}.chunks WHERE tsv @@ to_tsquery('english', $1) ORDER BY 5 DESC, chunk_id LIMIT $2`,
173:         [orQuery, k],
174:       );
175:       return res.rows.map((row, i) => ({
176:         chunkId: row.chunk_id, sourceId: row.source_id, text: row.text,
177:         section: row.section ?? null, score: Number(row.ts_rank_cd ?? row["?column?"] ?? 0), rank: i + 1,
178:       }));
179:     } finally {
180:       client.release();
181:     }
