184:   async denseSearch(vector: number[], k: number, hnswProbe = 16): Promise<ScoredChunk[]> {
185:     const literal = `[${vector.map((v) => Number(v)).join(",")}]`;
186:     const s = ident(this.schema);
187:     const client = await this.pool.connect();
188:     try {
189:       await client.query(`SET LOCAL hnsw.ef_search = ${Math.floor(hnswProbe)}`).catch(() => {});
190:       const res = await client.query(
191:         `SELECT chunk_id, source_id, text, section, 1 - (embedding <=> $1::vector) AS score ` +
192:           `FROM ${s}.chunks ORDER BY embedding <=> $1::vector, chunk_id LIMIT $2`,
193:         [literal, k],
194:       );
195:       return res.rows.map((row, i) => ({
196:         chunkId: row.chunk_id, sourceId: row.source_id, text: row.text,
197:         section: row.section ?? null, score: Number(row.score), rank: i + 1,
198:       }));
199:     } finally {
200:       client.release();
201:     }
