154: export function cosine(a: number[], b: number[]): number {
155:   let dot = 0;
156:   let na = 0;
157:   let nb = 0;
158:   const n = Math.min(a.length, b.length);
159:   for (let i = 0; i < n; i++) {
160:     const x = a[i] ?? 0;
161:     const y = b[i] ?? 0;
162:     dot += x * y;
163:     na += x * x;
164:     nb += y * y;
165:   }
166:   return dot / ((Math.sqrt(na) || 1) * (Math.sqrt(nb) || 1));
167: }

