372:   async search(query: string, limit = 8): Promise<SearchResult> {
373:     const trimmed = query.trim();
374:     if (!trimmed) {
375:       return { ok: true, indexed: true, schema: this.options.schema, items: [], trace: null, message: "empty query: no retrieval attempted." };
376:     }
377:     const boundedLimit = Math.max(1, Math.min(limit, 20));
378:     const pool = await this.poolConnected();
379:     const client = await pool.connect();
380:     try {
381:       const reg = await client.query("SELECT to_regclass($1)", [`${this.options.schema}.chunks`]);
382:       if (reg.rows[0]?.to_regclass == null) {
383:         return { ok: true, indexed: false, schema: this.options.schema, items: [], trace: null, message: NOT_INDEXED_MESSAGE };
384:       }
385:     } finally {
386:       client.release();
387:     }
388:     const probe = await this.embedder.embed(["dimension probe"]);
389:     const embIdentity = {
390:       provider: probe.provider,
391:       model: probe.model,
392:       dimension: probe.dimension,
393:       version: `${probe.provider}:${probe.model}:${probe.dimension}`,
394:     };
395:     const retriever = new Retriever(this.store(pool), this.embedder, this.options.retrieval);
396:     const trace: RetrievalTrace = await retriever.retrieve(trimmed);
397:     const lexicalRanks = new Map(trace.lexical.map((c) => [c.chunkId, c.rank]));
398:     const denseRanks = new Map(trace.dense.map((c) => [c.chunkId, c.rank]));
399:     const finalStage = this.options.retrieval.reranker !== "none" ? "reranked" : "fused";
400:     const items: SearchItem[] = trace.reranked.slice(0, boundedLimit).map((c) => ({
401:       chunk_id: c.chunkId,
402:       source_id: c.sourceId,
403:       section: c.section,
404:       rank: c.rank,
405:       score: c.score,
406:       text: c.text,
407:       lexical_rank: lexicalRanks.get(c.chunkId) ?? null,
408:       dense_rank: denseRanks.get(c.chunkId) ?? null,
409:       stage: finalStage,
410:     }));
411:     return {
412:       ok: true,
413:       indexed: true,
414:       schema: this.options.schema,
415:       items,
416:       trace: {
417:         query: trace.query,
418:         mode: this.options.retrieval.mode,
419:         lexical_count: trace.lexical.length,
420:         dense_count: trace.dense.length,
421:         fused_count: trace.fused.length,
422:         reranked_count: trace.reranked.length,
423:         lexical_ids: trace.lexical.map((c) => c.chunkId),
424:         dense_ids: trace.dense.map((c) => c.chunkId),
425:         fused_ids: trace.fused.map((c) => c.chunkId),
426:         reranked_ids: trace.reranked.map((c) => c.chunkId),
427:         latencies_ms: Object.fromEntries(
428:           Object.entries(trace.latenciesMs).map(([k, v]) => [k, Math.round(v * 100) / 100]),
429:         ),
430:         embedding: embIdentity,
431:         retrieval: {
432:           mode: this.options.retrieval.mode,
433:           lexical_k: this.options.retrieval.lexicalK,
434:           dense_k: this.options.retrieval.denseK,
435:           fusion_k: this.options.retrieval.fusionK,
436:           rerank_k: this.options.retrieval.rerankK,
437:           reranker: this.options.retrieval.reranker,
438:         },
439:         dense_executed: "dense" in trace.latenciesMs,
440:       },
441:     };
442:   }
