562:   async loopCreate(transition: Record<string, unknown>): Promise<Record<string, unknown>> {
563:     const pool = await this.poolConnected();
564:     const pgStore = new PostgresLoopStore(pool, this.options.schema);
565:     await pgStore.initialise();
566:     const event = validateLoopEvent({ kind: "create", at: new Date().toISOString(), ...(transition as object) });
567:     if (!event.eventId || !event.loopId) throw new EngineError("LOOP_INVALID", "loop create requires event_id and loop_id.");
568:     const existing = (await pgStore.list()).filter((e) => e.loopId === event.loopId);
569:     if (existing.length > 0) {
570:       const views = reduceLoopEvents(await pgStore.list());
571:       return { duplicate: true, ...(views.get(event.loopId) as unknown as Record<string, unknown>) };
572:     }
573:     await pgStore.append(event);
574:     const views = reduceLoopEvents(await pgStore.list());
575:     return { duplicate: false, ...(views.get(event.loopId) as unknown as Record<string, unknown>) };
576:   }
