585:   async openLoops(request: { action?: string; loop_id?: string; state?: LoopState; subject?: string; transition_kind?: string; limit?: number } = {}): Promise<Record<string, unknown>> {
586:     const action = request.action ?? "list";
587:     const pool = await this.poolConnected();
588:     const pgStore = new PostgresLoopStore(pool, this.options.schema);
589:     await pgStore.initialise();
590:     const views = reduceLoopEvents(await pgStore.list());
591:     const all = [...views.values()].sort((a, b) => (a.createdAt < b.createdAt ? -1 : 1));
592:     if (action === "get" || action === "history") {
593:       if (!request.loop_id?.trim()) throw new EngineError("LOOP_INVALID", `loops action '${action}' requires loop_id.`);
594:       const view = views.get(request.loop_id);
595:       if (!view) throw new EngineError("LOOP_INVALID", `no loop ${JSON.stringify(request.loop_id)}.`);
596:       return { ...(view as unknown as Record<string, unknown>) };
597:     }
598:     let filtered = all;
599:     if (request.state) filtered = filtered.filter((v) => v.state === request.state);
600:     if (request.subject) filtered = filtered.filter((v) => v.subject.includes(request.subject as string));
601:     if (request.transition_kind) filtered = filtered.filter((v) => v.transitionKind === request.transition_kind);
602:     const limit = request.limit ?? 20;
603:     return { loops: filtered.slice(0, limit), total: filtered.length };
604:   }
