614:   private async indexExplicitRecord(pool: Pool, record: { recordId: string; content: string; role: string }): Promise<{ chunks: number; embedded: number }> {
615:     const probe = await this.embedder.embed([record.content]);
616:     const store = this.store(pool);
617:     await store.initialise(probe.dimension);
618:     const sourceId = `memory://${record.recordId}`;
619:     await store.upsertSource(sourceId, "memory-record", sha1(record.content), null);
620:     const version = `${probe.provider}:${probe.model}:${probe.dimension}`;
621:     await store.replaceChunks(sourceId, [{
622:       chunkId: record.recordId.slice(0, 16).padEnd(16, "0"),
623:       sourceId,
624:       ordinal: 0,
625:       text: record.content,
626:       section: null,
627:       charStart: 0,
628:       charEnd: record.content.length,
629:       contentHash: sha1(record.content),
630:       chunker: "explicit:0.1.0",
631:       embeddingVersion: version,
632:       embedding: probe.vectors[0] ?? [],
633:     }]);
634:     return { chunks: 1, embedded: 1 };
635:   }
