667:   async writeRebuild(): Promise<Record<string, unknown>> {
668:     const pool = await this.poolConnected();
669:     const pgStore = new PostgresWriteStore(pool, this.options.schema);
670:     await pgStore.initialise();
671:     const mem = new MemoryWriteStore();
672:     void mem;
673:     let reindexed = 0;
674:     // Re-index every active record through the native baseline store.
675:     const client = await pool.connect();
676:     try {
677:       const s = ident(this.options.schema);
678:       const res = await client.query(`SELECT record_id, content, role FROM ${s}.memory_records WHERE state = 'active'`);
679:       for (const row of res.rows) {
