31: /** RRF: parameter-free fusion over ranks. Port of retrieval.reciprocal_rank_fusion. */
32: export function reciprocalRankFusion(rankings: ScoredChunk[][], k = 60): ScoredChunk[] {
33:   const scores = new Map<string, number>();
34:   const byId = new Map<string, ScoredChunk>();
35:   for (const ranking of rankings) {
36:     ranking.forEach((chunk, index) => {
37:       const rank = index + 1;
38:       scores.set(chunk.chunkId, (scores.get(chunk.chunkId) ?? 0) + 1 / (k + rank));
39:       if (!byId.has(chunk.chunkId)) byId.set(chunk.chunkId, chunk);
40:     });
41:   }
42:   const ordered = [...scores.keys()].sort((a, b) => {
43:     const diff = (scores.get(b) ?? 0) - (scores.get(a) ?? 0);
44:     if (diff !== 0) return diff;
45:     return a < b ? -1 : a > b ? 1 : 0;
46:   });
47:   return ordered.map((cid, i) => {
48:     const origin = byId.get(cid);
49:     if (!origin) throw new Error("RRF invariant violated: missing chunk");
50:     return {
51:       chunkId: cid,
52:       sourceId: origin.sourceId,
53:       text: origin.text,
54:       section: origin.section,
55:       score: scores.get(cid) ?? 0,
56:       rank: i + 1,
57:     };
58:   });
59: }
