61: /** Transparent test-double reranker: token overlap with the query. */
62: export function overlapRerank(query: string, chunks: ScoredChunk[], k: number): ScoredChunk[] {
63:   const queryTokens = new Set(query.toLowerCase().split(/\s+/).filter(Boolean));
64:   const scored = chunks.map((chunk) => {
65:     const chunkTokens = new Set(chunk.text.toLowerCase().split(/\s+/).filter(Boolean));
66:     let overlap = 0;
67:     for (const token of queryTokens) if (chunkTokens.has(token)) overlap += 1;
68:     return { overlap, chunk };
69:   });
70:   scored.sort((a, b) => {
71:     if (b.overlap !== a.overlap) return b.overlap - a.overlap;
72:     return a.chunk.chunkId < b.chunk.chunkId ? -1 : a.chunk.chunkId > b.chunk.chunkId ? 1 : 0;
73:   });
74:   return scored.slice(0, k).map(({ overlap, chunk }, i) => ({
75:     chunkId: chunk.chunkId,
76:     sourceId: chunk.sourceId,
77:     text: chunk.text,
78:     section: chunk.section,
79:     score: overlap,
80:     rank: i + 1,
