160:     const start = current.index ?? 0;
161:     const next = i + 1 < matches.length ? matches[i + 1] : undefined;
162:     const end = next?.index ?? text.length;
163:     spans.push([start, end, (current[1] ?? "").trim().slice(0, 120)]);
164:   }
