168: export function chunkSentenceAware(text: string, target: number, overlap: number): Array<[number, number]> {
169:   const sentences = splitSentences(text);
170:   if (sentences.length === 0) return [];
171:   const offsets: Array<[number, number]> = [];
172:   let cursor = 0;
173:   for (const sentence of sentences) {
174:     let at = text.indexOf(sentence, cursor);
175:     if (at < 0) at = cursor;
176:     offsets.push([at, at + sentence.length]);
177:     cursor = at + sentence.length;
178:   }
179:   const spans: Array<[number, number]> = [];
180:   let i = 0;
181:   while (i < sentences.length) {
182:     const startTuple = offsets[i];
183:     const endTuple = offsets[i];
184:     if (!startTuple || !endTuple) break;
185:     const start = startTuple[0];
186:     let end = endTuple[1];
187:     let j = i;
188:     while (j + 1 < sentences.length && (offsets[j + 1]?.[1] ?? 0) - start < target) {
189:       j += 1;
190:       end = offsets[j]?.[1] ?? end;
191:     }
192:     spans.push([start, end]);
193:     if (j + 1 >= sentences.length) break;
194:     let k = j;
195:     while (k > i && end - (offsets[k]?.[0] ?? 0) < overlap) k -= 1;
196:     if (k < j) i = Math.max(k, i + 1);
