import type { ChunkRow, ScoredChunk } from "../storage";
import type { TemporalEnvelope } from "../temporal/model";
import type { StandingEvent } from "../trust/model";
import type { ContextTraceRecord } from "../trace/model";
import type { LoopEvent } from "../loops/model";
import type { MemoryActionRecord, MemoryRecord } from "../write/model";

/** Semantic storage ports. Domain logic depends on these, never on pg.Pool. */

export interface BaselineStorePort {
  readonly kind: string;
  initialise(embeddingDim: number): Promise<void>;
  checkDimension(embeddingDim: number): Promise<void>;
  upsertSource(sourceId: string, artifactType: string, contentHash: string, timestamp: string | null): Promise<boolean>;
  knownSources(): Promise<Record<string, string>>;
  removeSource(sourceId: string): Promise<number>;
  replaceChunks(sourceId: string, rows: ChunkRow[]): Promise<void>;
  lexicalSearch(query: string, k: number): Promise<ScoredChunk[]>;
  denseSearch(vector: number[], k: number, hnswProbe?: number): Promise<ScoredChunk[]>;
  ensureHnsw(): Promise<boolean>;
  stats(): Promise<Record<string, unknown>>;
  orphanChunks(): Promise<number>;
  embeddingVersions(): Promise<string[]>;
  /** True when the underlying chunks table/store exists. */
  isInitialised(): Promise<boolean>;
  readProjectMeta(): Promise<Record<string, string>>;
  writeProjectMeta(entries: Record<string, string>, overwrite?: boolean): Promise<void>;
  capabilities(): StoreCapabilities;
}

export interface TemporalStorePort {
  initialise(): Promise<void>;
  append(envelope: TemporalEnvelope): Promise<{ duplicate: boolean }>;
  list(): Promise<TemporalEnvelope[]>;
  count(): Promise<number>;
  subjects(): Promise<string[]>;
  versions(): Promise<{ storeVersion: string | null; eventSchemaVersion: string | null }>;
}

export interface StandingStorePort {
  initialise(): Promise<void>;
  append(event: StandingEvent): Promise<{ duplicate: boolean }>;
  list(): Promise<StandingEvent[]>;
  count(): Promise<number>;
}

export interface TraceStorePort {
  initialise(): Promise<void>;
  put(trace: ContextTraceRecord): Promise<void>;
  get(traceId: string): Promise<ContextTraceRecord | null>;
  find(filters: {
    sourceId?: string; chunkId?: string; route?: string; workType?: string;
    terminalStage?: string; before?: string; after?: string; limit?: number;
  }): Promise<ContextTraceRecord[]>;
  count(): Promise<{ traces: number; oldest: string | null; newest: string | null }>;
}

export interface LoopStorePort {
  initialise(): Promise<void>;
  append(event: LoopEvent): Promise<{ duplicate: boolean }>;
  list(): Promise<LoopEvent[]>;
  count(): Promise<number>;
}

export interface WriteStorePort {
  initialise(): Promise<void>;
  putRecord(record: MemoryRecord): Promise<void>;
  getRecord(recordId: string): Promise<MemoryRecord | null>;
  updateRecordState(recordId: string, state: MemoryRecord["state"]): Promise<void>;
  putAction(action: MemoryActionRecord): Promise<void>;
  getAction(actionId: string): Promise<MemoryActionRecord | null>;
  getActionByIdempotency(key: string): Promise<MemoryActionRecord | null>;
  history(recordId: string): Promise<MemoryActionRecord[]>;
  counts(): Promise<{ records: number; actions: number; byAction: Record<string, number>; lastActionAt: string | null }>;
  /** Atomic multi-step write used by explicit-memory paths where available. */
  transaction?<T>(fn: () => Promise<T>): Promise<T>;
}

export type StoreCapabilities = {
  lexicalSearch: boolean;
  denseSearch: boolean;
  /** True only for a real vector index (pgvector/HNSW). JSON uses linear scan. */
  vectorIndex: boolean;
  transactions: boolean;
  tracePersistence: boolean;
  atomicWrite: boolean;
  remote: boolean;
  denseStrategy: "pgvector" | "linear-cosine" | "none";
};

export const POSTGRES_CAPABILITIES: StoreCapabilities = {
  lexicalSearch: true,
  denseSearch: true,
  vectorIndex: true,
  transactions: true,
  tracePersistence: true,
  atomicWrite: true,
  remote: false,
  denseStrategy: "pgvector",
};

export const JSON_CAPABILITIES: StoreCapabilities = {
  lexicalSearch: true,
  denseSearch: true,
  vectorIndex: false,
  transactions: false,
  tracePersistence: true,
  atomicWrite: true,
  remote: false,
  denseStrategy: "linear-cosine",
};

export const HTTP_CAPABILITIES: StoreCapabilities = {
  lexicalSearch: true,
  denseSearch: true,
  vectorIndex: true,
  transactions: true,
  tracePersistence: true,
  atomicWrite: true,
  remote: true,
  denseStrategy: "pgvector",
};

export type StorageBackendKind = "postgres" | "http" | "json";

import * as crypto from "node:crypto";
import * as fs from "node:fs/promises";
import * as path from "node:path";

/** Stable project identity without breaking existing isolation. */

export type ProjectIdentity = {
  /** Explicit configured ID wins when present. */
  projectId: string;
  /** Canonical local path (realpath, lowercased on win32). */
  canonicalPath: string;
  /** Derived postgres schema (existing semantics preserved). */
  schema: string;
  /** How the identity was derived. */
  source: "explicit" | "git-remote" | "local-path";
  /** Git remote slug when available, e.g. github:owner/repo. */
  gitSlug: string | null;
};

export async function canonicalProjectDir(directory: string): Promise<string> {
  let resolved: string;
  try {
    resolved = await fs.realpath(directory);
  } catch {
    resolved = path.resolve(directory);
  }
  return process.platform === "win32" ? resolved.toLowerCase() : resolved;
}

export async function schemaForProjectDir(directory: string): Promise<string> {
  const canonical = await canonicalProjectDir(directory);
  const digest = crypto.createHash("sha256").update(canonical).digest("hex").slice(0, 12);
  return `remembering_${digest}`;
}

async function gitSlugForDir(directory: string): Promise<string | null> {
  try {
    const raw = await fs.readFile(path.join(directory, ".git", "config"), "utf8").catch(() => null);
    if (raw) {
      const m = /url\s*=\s*(.+)/g;
      let match: RegExpExecArray | null;
      while ((match = m.exec(raw))) {
        const url = (match[1] ?? "").trim();
        const gh = url.match(/github\.com[:/]([^/]+\/[^/.]+?)(?:\.git)?\s*$/i);
        if (gh?.[1]) return `github:${gh[1]}`;
      }
      return null;
    }
  } catch { /* ignore */ }
  return null;
}

export async function resolveProjectIdentity(
  directory: string,
  opts: { explicitId?: string; schemaOverride?: string } = {},
): Promise<ProjectIdentity> {
  const canonicalPath = await canonicalProjectDir(directory);
  if (opts.explicitId?.trim()) {
    const projectId = opts.explicitId.trim();
    const schema = opts.schemaOverride ?? (await schemaForProjectDir(directory));
    return { projectId, canonicalPath, schema, source: "explicit", gitSlug: await gitSlugForDir(directory) };
  }
  const gitSlug = await gitSlugForDir(directory);
  // Preserve current isolation: schema still derives from the canonical path
  // so existing installs never merge. The git slug is advisory identity only.
  const schema = opts.schemaOverride ?? (await schemaForProjectDir(directory));
  const projectId = gitSlug ? `${gitSlug}#${schema}` : `local:${schema}`;
  return { projectId, canonicalPath, schema, source: gitSlug ? "git-remote" : "local-path", gitSlug };
}

import * as fs from "node:fs/promises";
import * as path from "node:path";

/** Atomic filesystem helpers for the JSON backend. */

export async function ensureDir(dir: string): Promise<void> {
  await fs.mkdir(dir, { recursive: true });
}

/** Atomic write: temp file + rename. Never leaves half-written JSON. */
export async function atomicWriteFile(file: string, content: string): Promise<void> {
  await ensureDir(path.dirname(file));
  const tmp = `${file}.${process.pid}.tmp`;
  await fs.writeFile(tmp, content, "utf8");
  try {
    const handle = await fs.open(tmp, "r");
    try {
      await handle.sync();
    } finally {
      await handle.close();
    }
  } catch { /* best effort fsync */ }
  await fs.rename(tmp, file);
}

export async function readJsonFile<T>(file: string, fallback: T): Promise<T> {
  try {
    const raw = await fs.readFile(file, "utf8");
    return JSON.parse(raw) as T;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return fallback;
    throw error;
  }
}

export async function appendJsonLine(file: string, value: unknown): Promise<void> {
  await ensureDir(path.dirname(file));
  await fs.appendFile(file, `${JSON.stringify(value)}\n`, "utf8");
}

export async function readJsonLines<T>(file: string): Promise<T[]> {
  let content: string;
  try {
    content = await fs.readFile(file, "utf8");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw error;
  }
  const out: T[] = [];
  for (const [i, line] of content.split("\n").entries()) {
    if (!line.trim()) continue;
    try {
      out.push(JSON.parse(line) as T);
    } catch {
      throw new Error(`corrupt JSONL at ${file}:${i + 1}`);
    }
  }
  return out;
}

/** Minimal async mutex per store file to serialize overlapping OpenCode ops. */
const locks = new Map<string, Promise<void>>();

export async function withFileLock<T>(key: string, fn: () => Promise<T>): Promise<T> {
  const prior = locks.get(key) ?? Promise.resolve();
  let release!: () => void;
  const current = new Promise<void>((resolve) => { release = resolve; });
  locks.set(key, prior.then(() => current));
  await prior;
  try {
    return await fn();
  } finally {
    release();
    if (locks.get(key) === current) locks.delete(key);
  }
}

import { cosine } from "../../embeddings";
import type { ChunkRow, ScoredChunk } from "../../storage";

/** BM25-like lexical scorer: real ranking, not substring matching. */

type DocStats = { tf: Map<string, number>; length: number };

export function tokenize(text: string): string[] {
  return text.toLowerCase().match(/[a-z0-9]+/g)?.filter((t) => t.length > 1) ?? [];
}

export function bm25Scores(
  query: string,
  docs: Array<{ chunkId: string; text: string }>,
  k1 = 1.2,
  b = 0.75,
): Map<string, number> {
  const N = docs.length;
  if (N === 0) return new Map();
  const docTokens = docs.map((d) => ({ id: d.chunkId, tokens: tokenize(d.text) }));
  const df = new Map<string, number>();
  const perDoc: DocStats[] = docTokens.map(({ tokens }) => {
    const tf = new Map<string, number>();
    for (const t of tokens) tf.set(t, (tf.get(t) ?? 0) + 1);
    for (const t of tf.keys()) df.set(t, (df.get(t) ?? 0) + 1);
    return { tf, length: tokens.length };
  });
  const avgLen = perDoc.reduce((n, d) => n + d.length, 0) / Math.max(1, perDoc.length);
  const qTerms = tokenize(query);
  const scores = new Map<string, number>();
  docTokens.forEach((doc, i) => {
    const stats = perDoc[i]!;
    let score = 0;
    for (const term of new Set(qTerms)) {
      const tf = stats.tf.get(term) ?? 0;
      if (!tf) continue;
      const docFreq = df.get(term) ?? 1;
      const idf = Math.log(1 + (N - docFreq + 0.5) / (docFreq + 0.5));
      const denom = tf + k1 * (1 - b + (b * stats.length) / Math.max(1, avgLen));
      score += idf * ((tf * (k1 + 1)) / denom);
    }
    if (score > 0) scores.set(doc.id, score);
  });
  return scores;
}

export function lexicalRank(query: string, rows: ChunkRow[], k: number): ScoredChunk[] {
  const scores = bm25Scores(query, rows.map((r) => ({ chunkId: r.chunkId, text: r.text })));
  const byId = new Map(rows.map((r) => [r.chunkId, r]));
  return [...scores.entries()]
    .sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1))
    .slice(0, k)
    .map(([chunkId, score], i) => {
      const row = byId.get(chunkId)!;
      return { chunkId, sourceId: row.sourceId, text: row.text, section: row.section, score, rank: i + 1 };
    });
}

/** Linear cosine scan over stored embeddings. Honest: not HNSW/pgvector. */
export function denseRank(queryVector: number[], rows: ChunkRow[], k: number): ScoredChunk[] {
  const scored = rows
    .filter((r) => Array.isArray(r.embedding) && r.embedding.length > 0)
    .map((r) => ({ row: r, score: cosine(queryVector, r.embedding) }))
    .filter((s) => Number.isFinite(s.score));
  scored.sort((a, b) => b.score - a.score || (a.row.chunkId < b.row.chunkId ? -1 : 1));
  return scored.slice(0, k).map((s, i) => ({
    chunkId: s.row.chunkId, sourceId: s.row.sourceId, text: s.row.text,
    section: s.row.section, score: s.score, rank: i + 1,
  }));
}

